import numpy as np

def build(noise):
    t = np.arange(400)
    return np.where(t<200,80.0,120.0) + 6*np.sin(2*np.pi*t/7) + noise

def wf(s,w):
    p=np.full(len(s),np.nan)
    for t in range(w,len(s)): p[t]=s[t-w:t].mean()
    return p

def mae(s,p,a=60,b=399): return np.abs(p-s)[a:b+1].mean()

def fwd_roll(s,p,span=30):
    ae=np.abs(p-s); out=np.full(len(s),np.nan)
    for t in range(len(s)-span+1):
        seg=ae[t:t+span]
        if not np.isnan(seg).any(): out[t]=seg.mean()
    return out

variants = {
 "default_rng normal":      lambda: np.random.default_rng(21).normal(0,10,400),
 "default_rng std_normal":  lambda: np.random.default_rng(21).standard_normal(400)*10,
 "RandomState normal":      lambda: np.random.RandomState(21).normal(0,10,400),
 "RandomState randn":       lambda: np.random.RandomState(21).randn(400)*10,
}
for name,gen in variants.items():
    s=build(gen())
    res={w:mae(s,wf(s,w)) for w in (3,7,14,28)}
    best=min(res,key=res.get)
    fr28=fwd_roll(s,wf(s,28))[200:241]; fr3=fwd_roll(s,wf(s,3))[200:241]
    print(f"{name:24s} best={best}  " + "  ".join(f"w{w}:{res[w]:.3f}" for w in res)
          + f"  fwdRoll28max={np.nanmax(fr28):.2f} fwdRoll3max={np.nanmax(fr3):.2f}")
